WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, DATE_TRUNC('HOUR', reading_ts) AS hour_window, MAX(session_no) FILTER (WHERE device_code = 'DV-01') AS dv_01_max_session_no, SIZE(COLLECT_SET(device_code)) AS num_device_codes, AVG(is_new_session) FILTER (WHERE device_code = 'DV-03') AS dv_03_avg_is_new_session FROM sessionized GROUP BY DATE_TRUNC('DAY', reading_ts), DATE_TRUNC('HOUR', reading_ts);
